/// <summary>
/// CB201_RebatesExtension_GSTchanges
/// TAMRebateCreateDocumentFinancialCustInvoice extension to handles the item sales tax information
/// </summary>
[ExtensionOf(classStr(TAMRebateCreateDocumentFinancialCustInvoice))]
final class METTAMRebateCreateDocumentFinancialCustInvoice_Extension
{
}

Method.Source:
/// <summary>
/// CB201_RebatesExtension_GSTchanges
/// Get Source transaction tax item group
/// </summary>
/// <returns>TaxItemGroup of source tramsactions</returns>
protected TaxItemGroup getTaxItemGroup()
{
    TaxItemGroup taxItemGroup = next getTaxItemGroup();

    if (this.getRebatePosting().METFollowTransItemGSTGroup == NoYes::Yes)
    {
        taxItemGroup = this.parmItemSalesTaxGroup();

    }

    // Task182820-CB272_SalesInvoicing-rebates-start
    if (TAMRebateParameters::find().METProcessByCustRebateInvByItemType)
    {
        rebateDocumentNotes = this.parmItemTypeDescription();
    }
    // Task182820-CB272_SalesInvoicing-rebates-end

    return taxItemGroup;
}

/// <summary>
/// Forces Free Text Invoice header creation when the reference customer account changes
/// </summary>
/// <returns>True if a new invoice header is required; otherwise, base result.</returns>
protected boolean needCreateHeader()
{
    boolean ret = next needCreateHeader();

    if (!ret && TAMRebateParameters::find().METProcessByCustRebateInvByItemType)
    {
        CustAccount activeCustomer = this.parmMetRebateRefAccount();

        if (activeCustomer && custInvoiceTable && custInvoiceTable.InvoiceAccount != activeCustomer)
        {
            ret = true;
        }
    }

    return ret;
}

/// <summary>
/// Sets the invoice recipient to the transaction-level rebate reference account
/// </summary>
/// <returns>Common buffer</returns>
protected Common createDocumentHeader()
{
    if (TAMRebateParameters::find().METProcessByCustRebateInvByItemType && this.parmMetRebateRefAccount())
    {
        rebatePostingAccount.parmRecipient(this.parmMetRebateRefAccount());
    }

    return next createDocumentHeader();
}
